import React, { useState, useRef, useEffect } from 'react';
import Tips from '../Tips/Tips';
import Employees from '../Employees/Employees';
import Summary from '../Summary/Summary';
import { GrAdd, GrUserManager, GrDocumentText } from 'react-icons/gr';
import './Tabs.css';

const tabs = [
  { title: 'Add Tips', icon: <GrAdd />, component: Tips },
  { title: 'Manage Employees', icon: <GrUserManager />, component: Employees },
  { title: 'View Summary', icon: <GrDocumentText />, component: Summary },
];

function Tabs() {
  const [selectedTab, setSelectedTab] = useState(1);

  function onTabClicked(e) {
    setSelectedTab(e.target.id);
  }

  return (
    <div className="tabs">
      <div className='tabOptions'>
        {tabs.map((tab, index) => (
          <React.Fragment key={index}>
            <input 
            type="radio" 
            id={`${index + 1}`} 
            name="tab" defaultChecked={index === 0} onClick={onTabClicked} />
            <label htmlFor={`tab${index + 1}`}>
              {tab.icon}
              <span>{tab.title}</span>
            </label>
          </React.Fragment>
        ))}
      </div>
      <div className='selectedTab'>
        {selectedTab === 1 && <Tips /> || selectedTab === 2 && <Employees /> || selectedTab === 3 && <Summary />}

      </div>
    </div>
  );
}

export default Tabs;
